local a=require("fcs.io.hwconfig")local b=require("fcs.io.tuningdefaults")local c={FILES={devbind="eh2_devbind.tbl",senscal="eh2_senscal.tbl",tuning="eh2_tuning.tbl",fuelcal="eh2_fuelcal.tbl"}}function c.defaults(d)local e=a.defaults()if d=="devbind"then return{thrusters=e.thrusters,sensors=e.sensors,fuelRelay=e.fuelRelay}end;if d=="senscal"then return e.bindings end;if d=="tuning"then return b.get()end;if d=="fuelcal"then return{fuel=require("fcs.fueltable").default}end;error("unknown cfg kind: "..tostring(d))end;function c.merge(d,f)f=f or{}if d=="senscal"and type(f)=="table"and f.signHeading~=nil and f.compassSign==nil then local g={}for h,i in pairs(f)do g[h]=i end;g.compassSign=f.signHeading;f=g end;return a.merge(f,c.defaults(d))end;function c.validate(d,j)if type(j)~="table"then return false,"not a table"end;local k=({devbind={"thrusters","sensors"},senscal={"signPitch","signHeading"},tuning={"gains","caps","feel"},fuelcal={"fuel"}})[d]for l,h in ipairs(k or{})do if j[h]==nil then return false,"missing "..h end end;return true end;function c.load(d,m)local n=m(c.FILES[d])if n==nil then return c.merge(d,{}),false,nil end;local f=textutils.unserialise(n)if type(f)~="table"then return c.merge(d,{}),true,"unparseable"end;return c.merge(d,f),true,nil end;function c.save(d,j,o)return o(c.FILES[d],textutils.serialise(j))end;function c.splitLegacy(p)return{devbind={thrusters=p.thrusters,sensors=p.sensors,fuelRelay=p.fuelRelay},senscal=p.bindings}end;function c.assembleHw(q,r)return{thrusters=q.thrusters,sensors=q.sensors,fuelRelay=q.fuelRelay,bindings=r}end;function c.tryAssemble(m)local s,t,u=c.load("devbind",m)local v,w,x=c.load("senscal",m)if u or x then return nil,u or x end;if not t or not w then return nil,nil end;return c.assembleHw(s,v)end;return c